using System.Text.Json;

namespace NntmuxControl.Web.Tests;

/// <summary>
/// NntmuxControlApi deserializes report() with JsonNamingPolicy.SnakeCaseLower,
/// which does not reliably round-trip every PHP key (e.g. a digit run right
/// after a word, as in `ewma_nzbs_per_10k`) -- this pins the known exception
/// and guards against silently reintroducing it.
/// </summary>
public sealed class OrchestratorReportDeserializationTests
{
    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    [Fact]
    public void Yield_group_ewma_field_round_trips_despite_the_digit_boundary()
    {
        const string json = """{"group":"alt.binaries.test","attempts":12,"ewma_nzbs_per_10k":4.3,"last_cursor_delta":9000,"last_attempt_at":1,"last_effective_at":2}""";

        var dto = JsonSerializer.Deserialize<YieldGroupDto>(json, JsonOptions);

        Assert.NotNull(dto);
        Assert.Equal(4.3, dto.EwmaNzbsPer10k);
    }
}
