const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://127.0.0.1:9452/', { waitUntil: 'networkidle', timeout: 30000 });
  await page.waitForTimeout(1500);

  // Click Drain -> should hit mock /api/mode with {action:set, mode:drain}
  const modeCalls = [];
  page.on('request', req => {
    if (req.url().includes('/api/mode')) {
      modeCalls.push({ url: req.url(), method: req.method(), body: req.postData() });
    }
  });

  await page.click('button:has-text("Drain")');
  await page.waitForTimeout(1000);

  // Free Run flow: click Free Run..., check confirm disabled, type wrong, type right, confirm
  await page.click('button:has-text("Free Run")');
  await page.waitForTimeout(300);
  const confirmBtnSelector = 'button.danger:has-text("Confirm Free Run")';
  const beforeDisabled = await page.isDisabled(confirmBtnSelector).catch(() => 'NOT FOUND');
  await page.fill('input[type=text]', 'nope');
  const stillDisabled = await page.isDisabled(confirmBtnSelector).catch(() => 'NOT FOUND');
  await page.fill('input[type=text]', 'free_run');
  const nowEnabled = await page.isDisabled(confirmBtnSelector).catch(() => 'NOT FOUND');
  await page.click(confirmBtnSelector);
  await page.waitForTimeout(1000);

  console.log('confirm button disabled before typing:', beforeDisabled);
  console.log('confirm button disabled with wrong text:', stillDisabled);
  console.log('confirm button disabled (false=enabled) with correct text:', nowEnabled);
  console.log('mode calls observed:', JSON.stringify(modeCalls, null, 2));

  await browser.close();
})();
